"""Alert ORM model — system-generated alerts and notifications."""

from datetime import datetime

from sqlalchemy import (
    Boolean,
    DateTime,
    Enum,
    ForeignKey,
    Integer,
    String,
    Text,
    func,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.database import Base


class Alert(Base):
    """Alert generated by the system based on threshold breaches or predictions."""

    __tablename__ = "alerts"

    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    hospital_id: Mapped[int] = mapped_column(Integer, ForeignKey("hospitals.id"), nullable=False)

    alert_type: Mapped[str] = mapped_column(
        Enum(
            "bed_shortage",
            "staff_shortage",
            "ambulance_shortage",
            "surge_predicted",
            "resource_low",
            "capacity_critical",
            "weather_alert",
            "mass_casualty",
            name="alert_type",
        ),
        nullable=False,
    )
    severity: Mapped[str] = mapped_column(
        Enum("critical", "warning", "info", name="alert_severity"),
        nullable=False,
        default="info",
    )
    title: Mapped[str] = mapped_column(String(255), nullable=False)
    message: Mapped[str] = mapped_column(Text, nullable=False)

    # Tracking
    acknowledged: Mapped[bool] = mapped_column(Boolean, default=False)
    acknowledged_by: Mapped[str | None] = mapped_column(String(255), nullable=True)
    acknowledged_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    resolved: Mapped[bool] = mapped_column(Boolean, default=False)
    resolved_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now()
    )

    # Relationships
    hospital: Mapped["Hospital"] = relationship("Hospital", back_populates="alerts")

    def __repr__(self) -> str:
        return f"<Alert(id={self.id}, type='{self.alert_type}', severity='{self.severity}')>"


# Avoid circular imports
from app.models.hospital import Hospital  # noqa: E402, F811
